CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,parent_id INT NULL,sort INT DEFAULT 0,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,category_id INT NOT NULL,origin VARCHAR(60),sold_by_type ENUM('pack','weight','volume','piece','variant') DEFAULT 'pack',unit_label VARCHAR(40),base_price DECIMAL(8,2) NOT NULL,min_qty DECIMAL(6,2) DEFAULT 1,qty_step DECIMAL(6,2) DEFAULT 1,age_restricted TINYINT(1) DEFAULT 0,stock INT DEFAULT 0,search_keywords TEXT,status ENUM('active','hidden') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY(category_id),FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_variants(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,label VARCHAR(80) NOT NULL,price DECIMAL(8,2) NOT NULL,sort INT DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS delivery_zones(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,codes VARCHAR(500) NOT NULL COMMENT 'outward postcodes, comma separated e.g. SE1,SE15',fee DECIMAL(6,2) NOT NULL,min_order DECIMAL(6,2) DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,ref VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(120),phone VARCHAR(40),email VARCHAR(160),method ENUM('collect','delivery') NOT NULL,address VARCHAR(255),town VARCHAR(100),postcode VARCHAR(12),zone VARCHAR(80),slot_date DATE NULL,slot_time VARCHAR(40),substitution ENUM('substitute','call','none') DEFAULT 'substitute',notes TEXT,subtotal DECIMAL(8,2),delivery_fee DECIMAL(6,2) DEFAULT 0,total DECIMAL(8,2),status ENUM('new','confirmed','preparing','ready','out','completed','cancelled') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,sku VARCHAR(30),name VARCHAR(200),variant VARCHAR(80),qty DECIMAL(7,2),unit VARCHAR(40),unit_price DECIMAL(8,2),line_total DECIMAL(8,2),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- EXAMPLE zones: replace the postcodes with the areas the shop really delivers to
INSERT INTO delivery_zones(name,codes,fee,min_order) VALUES('Zone 1 (nearby)','SE1,SE15,SE16',3.99,15),('Zone 2 (further out)','SE5,SE8,SE14,SE17',5.99,25);
CREATE TABLE IF NOT EXISTS promo_codes(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,type ENUM('percent','fixed') NOT NULL,value DECIMAL(8,2) NOT NULL,min_order DECIMAL(8,2) DEFAULT 0,expires DATE NULL,active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS banners(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,subtitle VARCHAR(200),link VARCHAR(255),btn VARCHAR(40),color TINYINT DEFAULT 0,sort INT DEFAULT 0,active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,name VARCHAR(60),rating TINYINT NOT NULL,body VARCHAR(800),approved TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY(product_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE orders ADD COLUMN promo_code VARCHAR(30) NULL,ADD COLUMN discount DECIMAL(8,2) DEFAULT 0;
-- EXAMPLE code (switched off): turn on and edit in Admin > Promo codes
INSERT INTO promo_codes(code,type,value,min_order,active) VALUES('WELCOME10','percent',10,20,0);
CREATE TABLE IF NOT EXISTS recipes(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(140) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,intro VARCHAR(300),steps TEXT,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_items(id INT AUTO_INCREMENT PRIMARY KEY,recipe_id INT NOT NULL,product_id INT NOT NULL,qty DECIMAL(6,2) DEFAULT 1,FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subscribers(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(160) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,pass_hash VARCHAR(255) NOT NULL,role ENUM('owner','manager','staff') NOT NULL DEFAULT 'staff',active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(40) PRIMARY KEY,v TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
